from utils import format_task


class TaskBoard:
    def __init__(self):
        self._tasks = []

    def add(self, title, done=False):
        self._tasks.append({"title": title, "done": done})

    def pending(self):
        return [t for t in self._tasks if not t["done"]]

    def render(self):
        return "\n".join(format_task(i, t) for i, t in enumerate(self._tasks))


if __name__ == "__main__":
    board = TaskBoard()
    board.add("Write capture fixtures", done=True)
    board.add("Normalize Gemini transcript")
    board.add("Add gemini harness chip")
    print(board.render())

def format_task(index, task):
    mark = "x" if task["done"] else " "
    return f"{index + 1}. [{mark}] {task['title']}"

